using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EvenOddSoulHeatAction", menuName = "Data/Battle/Battle Actions/Sothis/EvenOddSoulHeat Action")]
public class EvenOddSoulHeatAction : BattleAction
{
	[Header("Actions")]
	[SerializeField]
	private BattleAction evenAction;

	[SerializeField]
	private BattleAction oddAction;

	[Header("Soul Heat")]
	[SerializeField]
	protected bool resetSoulHeatAfterUse;

	[SerializeField]
	[HideIf("isEvilSoulHeatBased")]
	protected SoulHeat soulHeat;

	[Header("Custom Cast Amount")]
	[SerializeField]
	private bool enableCustomEvenCastAmount;

	[SerializeField]
	[ShowIf("enableCustomEvenCastAmount")]
	private int customEvenCastAmount;

	[SerializeField]
	private bool enableCustomOddCastAmount;

	[SerializeField]
	[ShowIf("enableCustomOddCastAmount")]
	private int customOddCastAmount;

	[Header("Evil Soul Heat")]
	[SerializeField]
	private bool isEvilSoulHeatBased;

	[SerializeField]
	[ShowIf("isEvilSoulHeatBased")]
	private EvilSoulHeat evilSoulHeat;

	[Header("Sandshaping")]
	[SerializeField]
	private bool sandshapingIncreaseSoulHeat;

	[Header("Eclipse Blast")]
	[SerializeField]
	private bool eclipseBlast;

	[SerializeField]
	[ShowIf("eclipseBlast")]
	private bool eclipseBlastCorruptionIncreaseSoulHeat;

	public BattleAction EvenAction => evenAction;

	public BattleAction OddAction => oddAction;

	public bool IsEvilSoulHeatBased => isEvilSoulHeatBased;

	public bool SandshapingIncreaseSoulHeat => sandshapingIncreaseSoulHeat;

	public bool EclipseBlast => eclipseBlast;

	public bool EclipseBlastCorruptionIncreaseSoulHeat => eclipseBlastCorruptionIncreaseSoulHeat;

	public int Counter
	{
		get
		{
			if (!isEvilSoulHeatBased)
			{
				return soulHeat.SoulHeatCounter;
			}
			return evilSoulHeat.EvilSoulHeatCounter;
		}
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (Counter % 2 == 0)
		{
			evenAction.CastTargetAmount(target, amount, source);
			if (eclipseBlastCorruptionIncreaseSoulHeat)
			{
				soulHeat.ModifySoulHeat(1);
			}
		}
		else
		{
			oddAction.CastTargetAmount(target, amount, source);
			if (sandshapingIncreaseSoulHeat)
			{
				soulHeat.ModifySoulHeat(1);
			}
		}
		ResetSoulHeat();
	}

	public override void Cast(GameObject source)
	{
		if (Counter % 2 == 0)
		{
			if (enableCustomEvenCastAmount)
			{
				evenAction.CastAmount(customEvenCastAmount, source);
			}
			else
			{
				evenAction.Cast(source);
			}
		}
		else
		{
			if (enableCustomOddCastAmount)
			{
				oddAction.CastAmount(customOddCastAmount, source);
			}
			else
			{
				oddAction.Cast(source);
			}
			if (sandshapingIncreaseSoulHeat)
			{
				soulHeat.ModifySoulHeat(1);
			}
		}
		ResetSoulHeat();
	}

	private void ResetSoulHeat()
	{
		if (!resetSoulHeatAfterUse)
		{
			return;
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 7, delegate
		{
			if (isEvilSoulHeatBased)
			{
				evilSoulHeat.ResetSoulHeat();
			}
			else
			{
				soulHeat.ResetSoulHeat();
			}
		});
	}
}
